# -*- coding: utf-8 -*-
"""
This module provides classes that store the alias to instance mappings.
"""
import logging

from .exceptions import AliasLookupError
from abc import ABCMeta, abstractmethod
from six import with_metaclass


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Store(with_metaclass(ABCMeta, object)):
    """Store abstraction.

    Every store implementation must inherit from this class, in order to be accepted by
    :class:`.LookupHandler`.
    """

    @abstractmethod
    def __len__(self):
        raise NotImplementedError

    @abstractmethod
    def add(self, instance, alias):
        """Remember instance by given alias."""
        raise NotImplementedError

    @abstractmethod
    def get(self, alias):
        """Return instance remembered by given alias."""
        raise NotImplementedError

    @abstractmethod
    def remove(self, alias):
        """Forget given alias."""
        raise NotImplementedError

    @abstractmethod
    def remove_object(self, instance):
        """Forget every alias that this instance is remembered by."""
        raise NotImplementedError

    @abstractmethod
    def reset(self):
        """Forget everything and revert to the starting state."""


class AliasStore(Store):
    """Basic lookup store implementation.

    Evaluates to False if it's empty, True otherwise.
    Can be used with :func:`len()` to check the number of aliases present in the store.


    Attributes
    ----------
    DEFAULT_ALIAS : str
        Whenever a method of this class is called with alias attribute omitted,
        this value is used as the lookup key.

    Parameters
    ----------
    name : :class:`str`, optional
        Sets the name of the store, used in its :func:`repr()`.

    Note
    ----
    This implementation is NOT thread-safe.

    """
    DEFAULT_ALIAS = 'default'

    def __init__(self, name=None):
        self._store = {}
        self.name = name
        self._log_init()

    def _log_init(self):
        logger.debug("Initialized store: {!r}.".format(self))

    def __len__(self):
        return len(self._store)

    def __repr__(self):
        reprstr = (
            "<{name} {clsname} at {id}>"
            if self.name is not None else
            "<{clsname} at {id}>"
        )
        return reprstr.format(
            name=self.name, clsname=self.__class__.__name__, id=hex(id(self))
        )

    def add(self, instance, alias=None):
        """Bind given instance to an alias.

        If the alias is already taken by another instance, that alias will be
        unbound from it, possibly making garbage collector collect it.
        """
        self._log_add(instance, alias)
        alias = self._get_default_if_needed(alias)
        self._store[alias] = instance

    def _log_add(self, instance, alias):
        logger.debug(
            "Binding {!r} to alias {!r} in {!r}.".format(instance, alias, self)
        )

    def get(self, alias=None):
        """Retrieve instance previously bound to the given alias.

        Raises AliasLookupError if unrecognized alias is given.
        """
        instance = self._get(alias)
        self._log_get(instance, alias)
        return instance

    def _get(self, alias=None):
        alias = self._get_default_if_needed(alias)
        self._check_alias_exists(alias)
        return self._store[alias]

    def _log_get(self, instance, alias):
        msg = "Resolved alias {!r} to {!r} from {!r}."
        logger.debug(msg.format(alias, instance, self))

    @property
    def all(self):
        """Retrieve list of all stored items.

        :return: All aliases with corresponding instances.
        :rtype: list
        """
        return self._store.items()

    @classmethod
    def _get_default_if_needed(cls, alias):
        return alias or cls.DEFAULT_ALIAS

    def _check_alias_exists(self, alias):
        if alias not in self._store:
            if alias == self.DEFAULT_ALIAS:
                self._raise_no_default_set()
            self._raise_unrecognized_alias(alias)

    def _raise_no_default_set(self):
        logger.debug("Resolving default alias failed in {!r}.".format(self))
        raise AliasLookupError(
            "Default alias used, but no object set as default."
        )

    def _raise_unrecognized_alias(self, alias):
        logger.debug("Resolving alias failed in {!r}.".format(self))
        raise AliasLookupError("Unrecognized alias: {!r}.".format(alias))

    # XXX: why is this removing all aliasses? In the next major version, change
    # it to only the one specified.
    def remove(self, alias=None):
        """Remove instance bound to the given alias.

        This method will also remove other aliases, that are used to reference
        the instance bound to the given one.
        Raises AliasLookupError if unrecognized alias is given.
        """
        instance = self._get(alias)
        bound_aliases = self._find_all_aliases_of_instance(instance)
        for alias in bound_aliases:
            del self._store[alias]
        self._log_removed_all_occurences(instance, bound_aliases)

    def _find_all_aliases_of_instance(self, instance):
        return [k for k, v in self._store.items() if v == instance]

    def remove_object(self, instance):
        """Find and remove every occurence of instance in the store.

        Returns True if at least one alias with the instance was found,
        False otherwise.
        """
        if instance not in self._store.values():
            return False
        aliases = self._find_all_aliases_of_instance(instance)
        for alias in aliases:
            del self._store[alias]

        self._log_removed_all_occurences(instance, aliases)
        return True

    def _log_removed_all_occurences(self, instance, aliases):
        aliases_list = ', '.join(repr(alias) for alias in aliases)
        msg = "Unbound {!r} from all its aliases in {!r}: {}."
        logger.debug(msg.format(instance, self, aliases_list))

    def reset(self):
        self._log_reset()
        self.__init__()

    def _log_reset(self):
        logger.debug("Resetting {!r}.".format(self))


class SeparateDefaultAliasStore(AliasStore):
    """Lookup store implementation with separated field for default alias.

    Whenever a method of this class is called with alias argument omitted,
    separate internal field is used to fetch / store an object, instead of
    alias "default".

    This means, that using alias "default" is now possible, i.e. there are no
    collisions between alias="default" and alias=None

    Evaluates to False if it's empty, True otherwise.

    Can be used with len() to check the number of aliases present in the store.

    This implementation is NOT thread-safe.

    The 'name' argument sets the name of the store, and is used in its repr().
    """

    def __init__(self, name=None):
        super(SeparateDefaultAliasStore, self).__init__(name=name)
        self._default_alias = None

    def __len__(self):
        return (
            super(SeparateDefaultAliasStore, self).__len__()
            + (1 if self._default_alias else 0)
        )

    def add(self, instance, alias=None):
        """Bind given instance to an alias.

        Whenever alias attribute is omitted or is None, instance will be stored
        in a separate field reserved for default instance.

        If the alias is already taken by another instance, that alias will be
        unbound from it, possibly making garbage collector collect it.
        """
        self._log_add(instance, alias)
        if not alias:
            self._default_alias = instance
        else:
            self._store[alias] = instance

    def get(self, alias=None):
        """Retrieve instance previously bound to the given alias.

        Whenever alias attribute is omitted or is None, instance assigned as
        default will be returned.

        Raises AliasLookupError if unrecognized alias is given or default
        instance is requested and it is empty.
        """
        instance = self._get(alias)
        self._log_get(instance, alias)
        return instance

    def _get(self, alias=None):
        self._check_alias_exists(alias)
        if not alias:
            instance = self._default_alias
        else:
            instance = self._store[alias]
        return instance

    def _check_alias_exists(self, alias):
        if alias is not None and alias not in self._store:
            self._raise_unrecognized_alias(alias)
        elif alias is None and self._default_alias is None:
            self._raise_no_default_set()

    def remove(self, alias=None):
        """Remove instance bound to the given alias.

        Whenever alias attribute is omitted or is None, instance assigned as
        default will be the one to be removed from the store.

        This method will also remove other aliases, that are used to reference
        the instance bound to the given one.

        Raises AliasLookupError if unrecognized alias is given.
        """
        if alias:
            if self._get(alias) == self._default_alias:
                self._default_alias = None
            super(SeparateDefaultAliasStore, self).remove(alias)
        else:
            if self._default_alias:
                super(SeparateDefaultAliasStore, self).remove(alias)
                self._default_alias = None
            else:
                self._raise_default_already_removed()

    def _raise_default_already_removed(self):
        logger.debug("Unbinding alias failed in {!r}.".format(self))
        raise AliasLookupError(
            "Nothing to unbind from default alias, as it's already empty."
        )

    def remove_object(self, instance):
        """Find and remove every occurrence of instance in the store.

        Returns True if at least one alias with the instance was found, False
        otherwise.
        """
        is_default = instance == self._default_alias
        is_stored = instance in self._store.values()
        if is_default or is_stored:
            if is_default:
                self._default_alias = None
            if is_stored:
                super(SeparateDefaultAliasStore, self).remove_object(instance)
            return True
        return False
